contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 mintAmount, uint256 burnValue) public {
        require(mintAmount > 0);
        require(burnValue > 0);
        c.mintToken(address(this), mintAmount);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supBefore = c.totalSupply();
        bool reverted;
        uint256 balAfter;
        uint256 supAfter;
        if (burnValue <= balBefore) {
            bool ok = c.burn(burnValue);
            balAfter = c.balanceOf(address(this));
            supAfter = c.totalSupply();
            assert(ok && balAfter == balBefore - burnValue && supAfter == supBefore - burnValue && !reverted);
        } else {
            try c.burn(burnValue) { reverted = false; } catch { reverted = true; }
            balAfter = c.balanceOf(address(this));
            supAfter = c.totalSupply();
            assert(reverted && balAfter == balBefore && supAfter == supBefore);
        }
    }
    receive() external payable {}
}

