contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 value) public {
        require(to != address(0));
        require(value > 0);
        require(c.balanceOf(address(this)) >= value);
        c.freezeAccount(address(this), true);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);
        bool reverted;
        bool ok2;
        // frozen: transfer must revert
        bool r1;
        try c.transfer(to, value) { r1 = false; } catch { r1 = true; }
        reverted = r1;
        uint256 balFrozen = c.balanceOf(address(this));
        uint256 toBalFrozen = c.balanceOf(to);
        c.freezeAccount(address(this), false);
        // unfrozen: transfer must succeed
        try c.transfer(to, value) { ok2 = true; } catch { ok2 = false; }
        assert(reverted && balFrozen == balBefore && toBalFrozen == toBalBefore && ok2 && c.balanceOf(address(this)) == balBefore - value && c.balanceOf(to) == toBalBefore + value);
    }
    receive() external payable {}
}

