contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 mintAmount, uint256 transferAmount) public {
        require(recipient != address(0));
        require(recipient != address(this));
        require(transferAmount <= mintAmount);
        c.mintToken(address(this), mintAmount);
        c.freezeAccount(recipient, true);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 recipBefore = c.balanceOf(recipient);
        uint256 tsBefore = c.totalSupply();
        bool reverted;
        try c.transfer(recipient, transferAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter = c.balanceOf(address(this));
        uint256 recipAfter = c.balanceOf(recipient);
        uint256 tsAfter = c.totalSupply();
        c.freezeAccount(recipient, false);
        bool secondOk;
        try c.transfer(recipient, transferAmount) {
            secondOk = true;
        } catch {
            secondOk = false;
        }
        assert(
            reverted &&
            balAfter == balBefore &&
            recipAfter == recipBefore &&
            tsAfter == tsBefore &&
            secondOk &&
            c.balanceOf(address(this)) == balBefore - transferAmount &&
            c.balanceOf(recipient) == recipBefore + transferAmount &&
            c.totalSupply() == tsBefore
        );
    }
    receive() external payable {}
}
